    pg("Les files de messages", "découpler les services", "archi",
       "Une <b>file de messages</b> transporte des messages entre producteurs et consommateurs, qui travaillent chacun à leur rythme.",
       (("outil", "modèle", "usage"), ("Redis (listes, streams)", "file simple", "petites charges"), ("RabbitMQ", "file avec accusés de réception", "tâches, routage"), ("Kafka, Redpanda", "journal d’événements rejouable", "flux massifs, analytique"), ("SQS, Pub/Sub, Service Bus", "services gérés", "cloud")),
       ["Absorber les pics : 10 000 documents arrivent, les travailleurs les traitent au rythme permis par les limites d’API.", "Découpler : l’ingestion ne dépend pas de la disponibilité du service de plongements.", "Penser « au moins une fois » : un message peut être livré deux fois, d’où l’idempotence."]),
    pg("Authentification et autorisation", "qui est-ce, et a-t-il le droit ?", "archi",
       "<b>Authentifier</b>, c’est vérifier l’identité ; <b>autoriser</b>, c’est vérifier les droits.",
       ["Utilisateurs : OAuth 2.0 / OpenID Connect via un fournisseur d’identité (Auth0, Keycloak, Entra ID, Google), jetons JWT vérifiés à chaque requête.", "Services : clés d’API par client, avec portée et rotation ; identités du cloud entre services.", "Autorisation : rôles (RBAC) ou attributs (ABAC), vérifiés côté serveur pour chaque ressource.", "<b>Propager l’identité jusqu’aux outils et à la recherche</b> : un agent ou un RAG ne doit jamais lire ou faire plus que l’utilisateur qu’il sert."],
       fiche=F("Vérifier un jeton dans FastAPI", "", [
           ("Schéma", "", "bearer = HTTPBearer()"),
           ("Dépendance", "", "async def utilisateur_courant(c = Depends(bearer)) -> User:\n    claims = jwt.decode(c.credentials, cle_publique, audience='api', algorithms=['RS256'])\n    return await users.get(claims['sub'])", "blue"),
           ("Autoriser", "", "if doc.tenant != user.tenant: raise HTTPException(404)", "red"),
           ("Propager", "", "rag.recuperer(q, tenant=user.tenant, groupes=user.groupes)")])),
