       "```mlflow.set_experiment('rag-support')\nwith mlflow.start_run():\n    mlflow.log_params({'chunk_size': 600, 'reranker': 'bge-v2-m3', 'prompt': 'v8'})\n    mlflow.log_metrics({'rappel@10': 0.91, 'fidelite': 0.94, 'cout_par_requete': 0.012})\n    mlflow.log_artifact('evals/resultats.jsonl')\nmlflow.anthropic.autolog()   # traces automatiques des appels",
