       "```from langfuse import observe, get_client\n@observe()\nasync def repondre(question: str):\n    docs = await recuperer(question)          # étape tracée\n    return await generer(question, docs)      # appels LLM tracés\nprompt = get_client().get_prompt('support-systeme', label='production')",
